        areaValue = Number(selectedCountry.area_sq_mi);
        densityValue = populationValue / areaValue;

        area.textContent = `${areaValue.toLocaleString()} square miles`;
        densityUnit.textContent = "square mile";
      } else {
        areaValue = Number(selectedCountry.area_sq_mi) * 2.58999;
        densityValue = populationValue / areaValue;

        area.textContent = `${areaValue.toLocaleString(undefined, {
          maximumFractionDigits: 2
        })} square kilometres`;

        densityUnit.textContent = "square kilometre";
      }

      density.textContent = densityValue.toLocaleString(undefined, {
        maximumFractionDigits: 2
      });
    }

    countrySelect.addEventListener("change", () => {
      const selectedName = countrySelect.value;

      if (!selectedName) {
        countryDisplay.style.display = "none";
        selectedCountry = null;
        return;
      }

      const country = countries.find(c => c.name === selectedName);
      if (country) {
        displayCountry(country);
      }
    });

    areaUnit.addEventListener("change", updateAreaAndDensity);

    wikiBtn.addEventListener("click", () => {
      if (!selectedCountry) return;

      const wikiUrl = `https://en.wikipedia.org/wiki/${encodeURIComponent(selectedCountry.name)}`;
      window.open(wikiUrl, "_blank");
    });

    loadCountries();
  </script>

